const ahora = new Date();

return [
  {
    json: {
      id_ejecucion: 'CLAS-SIN-' + Date.now(),
      id_incidente: 'INC-' + Date.now(),
      flujo: '01',
      proceso: 'clasificador_correos',
      escenario: 'sin_seguridad',
      remitente: 'usuario@ejemplo.com',
      asunto: 'Actualización urgente de contraseña',
      cuerpo: 'Ingrese al siguiente enlace para actualizar inmediatamente su contraseña.',
      categoria_real: 'phishing',
      hora_ingreso: ahora.toISOString().slice(0, 19).replace('T', ' ')
    }
  }
];

return items.map(item => {
  const texto = `${item.json.asunto} ${item.json.cuerpo}`.toLowerCase();

  let categoria = 'legitimo';

  const palabrasPhishing = [
    'contraseña',
    'password',
    'urgente',
    'actualizar inmediatamente',
    'verifique su cuenta',
    'enlace'
  ];

  const palabrasSpam = [
    'oferta',
    'promoción',
    'gratis',
    'descuento',
    'premio'
  ];

  if (palabrasPhishing.some(p => texto.includes(p))) {
    categoria = 'phishing';
  } else if (palabrasSpam.some(p => texto.includes(p))) {
    categoria = 'spam';
  }

  const deteccion = new Date();

  item.json.categoria_sistema = categoria;
  item.json.clasificacion_correcta = categoria === item.json.categoria_real;
  item.json.hora_deteccion = deteccion.toISOString().slice(0, 19).replace('T', ' ');

  return item;
});
